// Generated artifact: maintain platform implementations in their standalone files.
import fs from 'node:fs';
const publicDir = new URL('../public/', import.meta.url);
const entries = [
  ['CODEFORCES', 'cf-helper.user.js', ['codeforces.com', 'www.codeforces.com']],
  ['LUOGU', 'luogu-helper.user.js', ['www.luogu.com.cn', 'luogu.com.cn']],
  ['QOJ', 'qoj-helper.user.js', ['qoj.ac']],
];
const sources = entries.map(([platform, file, hosts]) => ({ platform, hosts, source: fs.readFileSync(new URL(file, publicDir), 'utf8').replace(/\r\n/g, '\n') }));
const matches = new Set(sources.flatMap(({ source }) => [...source.matchAll(/^\/\/ @match\s+(.+)$/gm)].map(m => m[1].trim())));
const grants = new Set(sources.flatMap(({ source }) => [...source.matchAll(/^\/\/ @grant\s+(.+)$/gm)].map(m => m[1].trim())));
const header = [
  '// ==UserScript==',
  '// @name         SWUFE Singularity OJ - All Platforms Helper',
  '// @namespace    https://oj.example.com',
  '// @version      1.0',
  '// @description  One installation for Codeforces, Luogu and QOJ. Disable standalone SWUFE helpers before enabling this bundle.',
  ...[...matches].map(m => '// @match        ' + m),
  ...[...grants].map(g => '// @grant        ' + g),
  '// @connect      *', '// @run-at       document-end', '// @noframes', '// ==/UserScript==',
].join('\n');
const body = sources.map(({ platform, hosts, source }) => {
  const code = source.replace(/^\/\/ ==UserScript==[\s\S]*?\/\/ ==\/UserScript==\s*/, '').trim();
  return `if (isOj || ${JSON.stringify(hosts)}.indexOf(host) !== -1) {\n/* BEGIN ${platform} */\n${code}\n/* END ${platform} */\n}`;
}).join('\n\n');
const result = `${header}\n\n// Generated by scripts/build-helper-bundle.mjs. Do not edit directly.\n(function() {\n'use strict';\nvar host = location.hostname;\nvar isOj = ['test.singularitylab.online', 'singularitylab.online', 'localhost', '127.0.0.1'].indexOf(host) !== -1;\n${body}\n})();\n`;
fs.writeFileSync(new URL('oj-helpers.user.js', publicDir), result);
console.log('Built unified helper from the three current platform implementations.');
